/**
 * Model ApprovalRequestStep
 * 
 */
export type ApprovalRequestStep = $Result.DefaultSelection<Prisma.$ApprovalRequestStepPayload>
/**
 * Model ApprovalAction
 * 
 */
export type ApprovalAction = $Result.DefaultSelection<Prisma.$ApprovalActionPayload>
/**
 * Model ApprovalDelegation
 * "I'm on leave 12–20 Aug, Priya approves for me." Consulted at approval
 * time, so a delegation created after a request is raised still applies.
 */
export type ApprovalDelegation = $Result.DefaultSelection<Prisma.$ApprovalDelegationPayload>
/**
 * Model Role
 * A role a customer can actually create. System roles (isSystem) mirror the
 * six UserRole enum values and cannot be deleted, so existing JWTs and the
 * e2e suite keep working; everything else is customer-defined.
 */
export type Role = $Result.DefaultSelection<Prisma.$RolePayload>
/**
 * Model Permission
 * The catalog of what can be permitted. Global (no orgId) and seeded from
 * utils/permissions.ts PERMISSION_CATALOG so code and data can't drift.
 */
export type Permission = $Result.DefaultSelection<Prisma.$PermissionPayload>
/**
 * Model RolePermission
 * 
 */
export type RolePermission = $Result.DefaultSelection<Prisma.$RolePermissionPayload>
/**
 * Model FieldPermission
 * Per-field visibility. Absent row = inherit the resource-level permission,
 * which keeps the table small: only exceptions are stored.
 */
export type FieldPermission = $Result.DefaultSelection<Prisma.$FieldPermissionPayload>
/**
 * Model KnowledgeSource
 * 
 */
export type KnowledgeSource = $Result.DefaultSelection<Prisma.$KnowledgeSourcePayload>
/**
 * Model KnowledgeDocument
 * 
 */
export type KnowledgeDocument = $Result.DefaultSelection<Prisma.$KnowledgeDocumentPayload>
/**
 * Model KnowledgeChunk
 * 
 */
export type KnowledgeChunk = $Result.DefaultSelection<Prisma.$KnowledgeChunkPayload>
/**
 * Model AiProvider
 * A configured LLM vendor. Null orgId = platform-level default available to
 * every tenant; a row with an orgId is that customer's own key (§80's
 * "customer-managed API keys"). apiKey is encrypted via utils/crypto.ts.
 */
export type AiProvider = $Result.DefaultSelection<Prisma.$AiProviderPayload>
/**
 * Model AiModelConfig
 * 
 */
export type AiModelConfig = $Result.DefaultSelection<Prisma.$AiModelConfigPayload>
/**
 * Model AiInteractionLog
 * Every LLM round-trip, one row. This is what makes §41 governance, §78
 * feedback, §79 observability and §81 cost control possible — and it's why
 * an AI-performed action stops being indistinguishable from a human one in
 * the audit log.
 */
export type AiInteractionLog = $Result.DefaultSelection<Prisma.$AiInteractionLogPayload>
/**
 * Model AiBudget
 * Spend ceiling per org per period. `hardStop` decides whether hitting the
 * limit degrades gracefully (skip AI, return the non-AI fallback) or errors.
 */
export type AiBudget = $Result.DefaultSelection<Prisma.$AiBudgetPayload>

